-- Itemised history (Aizat, 9 Oct 2026) + Scheduled balance rule.
--
-- 1. BearHaus only: the 27 "Opening balance adjustment" lumps (14/15 Jul 2026) are replaced by
--    one plan row per fund per month, May 2025 → Jul 2026, reconstructed from the frozen
--    Google Sheet Summary (month-to-month movement minus that month's manual rows).
--    Float's rows are the sheet's leftover NET of daily spending — the sheet counted spending
--    down inside Float; labelled accordingly. 29 of 36 funds land identical to the cent.
--    The 7 that move do so by exactly the rows the sheet mis-filed (wrong-year typos and
--    pre-entered future instalments) or the two hand-corrected anchors — see the assertion
--    below, which aborts the whole migration if anything else changes.
-- 2. Everyone: fund_balances now ignores future-dated rows ("Scheduled" transactions) — both
--    fund rows and daily spending — so a pre-entered instalment only counts from its date.

begin;

create temp table _before as
  select fund_id, name, round(balance, 2) as balance
  from public.fund_balances where household_id = '82f25ed0-bd15-4089-a184-833137120d7f';

delete from public.fund_transactions
 where household_id = '82f25ed0-bd15-4089-a184-833137120d7f'
   and remarks = 'Opening balance adjustment — migrated from Google Sheets Summary (Jul 2026)';


-- self-check against the OLD view (still in place at this point)
do $$
declare
  bad text;
begin
  with expected(name, delta) as (values
    ('Anne''s Savings SG',        68.00),   -- 14 Dec "2026" wedding angbao (typo for 2025)
    ('Claire''s Savings SG',      68.00),   -- same
    ('Dry Powder AU (Paige)',    265.00),   -- 9 Aug "2026" Joyful SG60 (typo for 2025)
    ('Monthly Expenses (Paige)', -39.00),   -- Nov/Dec "2026" rows (typo for 2025)
    ('Taxes Fund SG (Aizat)',   -942.55),   -- Property Tax 7–11 of 11, pre-entered Aug–Dec 2026
    ('Future DreamHouse SG',    -191.70),   -- itemised Jan–Apr 2025 rows vs sheet "Previous"
    ('Float',                   -231.98)    -- sheet's final Jul 2026 figure vs hand-corrected anchor
  )
  select string_agg(format('%s: %s → %s (expected %s)', b.name, b.balance, round(a.balance,2),
                           b.balance + coalesce(e.delta, 0)), '; ')
    into bad
  from _before b
  join public.fund_balances a on a.fund_id = b.fund_id
  left join expected e on e.name = b.name
  where abs(round(a.balance, 2) - (b.balance + coalesce(e.delta, 0))) >= 0.005;
  if bad is not null then
    raise exception 'itemised history: unexpected balance change — %', bad;
  end if;
end $$;

-- 2. Scheduled rule: a row dated after today has not happened yet
drop view if exists public.fund_balances;
create view public.fund_balances with (security_invoker = 'true') as
select f.household_id,
       f.id as fund_id,
       f.name,
       f.country,
       f.currency,
       f.is_active,
       f.sort_order,
       f.group_name,
       f.is_leftover_target,
       f.is_spend_pot,
       coalesce(sum(case when t.date > current_date then 0
                         when t.type = 'income' then t.amount else (- t.amount) end), 0)
       - case when f.is_spend_pot and h.pot_start is not null then
           coalesce((select sum(de.amount) from public.daily_expenses de
                      where de.household_id = f.household_id
                        and de.currency = f.currency
                        and de.category <> 'Payment'
                        and de.date >= h.pot_start
                        and de.date <= current_date), 0)
         else 0 end as balance
from public.funds f
join public.households h on h.id = f.household_id
left join public.fund_transactions t on t.fund_id = f.id
group by f.id, h.pot_start;

grant all on table public.fund_balances to anon, authenticated, service_role;

commit;
